CREATE VIRTUAL TABLE t2 USING fts4(tokenize=unicode61, x); INSERT INTO t2(x) VALUES('Enhance the INSERT syntax to allow multiple rows to be inserted via the VALUES clause.'),('Enhance the CREATE VIRTUAL TABLE command to support the IF NOT EXISTS clause.'),('Added the sqlite3_stricmp() interface as a counterpart to sqlite3_strnicmp().'),('Added the sqlite3_db_readonly() interface.'),('Added the SQLITE_FCNTL_PRAGMA file control, giving VFS implementations the ability to add new PRAGMA statements or to override built-in PRAGMAs.'),('Queries of the form: "SELECT max(x), y FROM table" returns the value of y on the same row that contains the maximum x value.'),('Added support for the FTS4 languageid option.'),('Documented support for the FTS4 content option. This feature has actually been in the code since version 3.7.9 but is only now considered to be officially supported.'),('Pending statements no longer block ROLLBACK. Instead, the pending statement will return SQLITE_ABORT upon next access after the ROLLBACK.'),('Improvements to the handling of CSV inputs in the command-line shell'),('Fix a bug introduced in version 3.7.10 that might cause a LEFT JOIN to be incorrectly converted into an INNER JOIN if the WHERE clause indexable terms connected by OR.'); UPDATE t2 SET x=replace(x,'A','Ä'); UPDATE t2 SET x=replace(x,'E','Ë'); UPDATE t2 SET x=replace(x,'I','Ï'); UPDATE t2 SET x=replace(x,'O','Ö'); UPDATE t2 SET x=replace(x,'U','Ü'); UPDATE t2 SET x=replace(x,'Y','Ÿ'); UPDATE t2 SET x=replace(x,'H','Ḧ'); UPDATE t2 SET x=replace(x,'W','Ẅ'); UPDATE t2 SET x=replace(x,'X','Ẍ'); UPDATE t2 SET x=replace(x,'a','ä'); UPDATE t2 SET x=replace(x,'e','ë'); UPDATE t2 SET x=replace(x,'i','ï'); UPDATE t2 SET x=replace(x,'o','ö'); UPDATE t2 SET x=replace(x,'u','ü'); UPDATE t2 SET x=replace(x,'y','ÿ'); UPDATE t2 SET x=replace(x,'h','ḧ'); UPDATE t2 SET x=replace(x,'w','ẅ'); UPDATE t2 SET x=replace(x,'x','ẍ');